import { writeFile } from "node:fs/promises";
import { artwork } from "./splash/artwork.mjs";
import { legendContent } from "./splash/content.mjs";

const { textDefs, hands } = artwork(await legendContent());
await writeFile(new URL("../components/splash/map/print.generated.ts", import.meta.url),
  "// Generated by npm run splash:generate. Shapes are pre-rasterized; only lettering stays live.\n" +
  `export const printLettering = ${JSON.stringify(textDefs)};\nexport const hands = ${JSON.stringify(hands)};\n`);
